#include "stdafx.h"#include "HcdRsu.h"#include "StateSer.h"enum EKeys{  sKeyNULL      = 0,  sKeySheetCount= 0xabfd9431,  sKeySheet     = 0x31f63ff3,  sKeyEnd       = 0x5fad99e6,  sKeyVersion   = 0x554808C6,};static const DWORD s_VersionState = 0x00000001;int KHcdRsu::StateSaveL( LPCSTR pszPath ){  OutputDebugString( m_szObjName );  OutputDebugString( "     HCD::SaveState...\n" );  DWORD s = GetTickCount();  KStateSer saverImpl( pszPath, true );  IStateSer *piSaver = &saverImpl;  saverImpl.StartSave();  piSaver->Write( sKeyVersion );  piSaver->Write( s_VersionState );  piSaver->Write( sKeySheetCount );  piSaver->Write( m_nSheets );  for( size_t n=0; n<m_nSheets; ++n )  {    KHcdSheet* pSheet = &m_pSheets[n];    piSaver->Write( sKeySheet );    piSaver->Write( pSheet->GetTreeName() );    piSaver->Write( pSheet->WorksheetIndex );    DWORD posStart = piSaver->GetPosition();    DWORD l = piSaver->Write( posStart );    pSheet->SaveState( *piSaver, s_VersionState );    DWORD posEnd = piSaver->GetPosition();    DWORD length = posEnd - posStart - l;    piSaver->WriteAtPosition( posStart, length );  }  saverImpl.Write( sKeyEnd );  saverImpl.SaveCompleted();  DWORD c = GetTickCount();  DWORD d = c - s;  char szDebug[512] = {};  sprintf_s( szDebug, "%s   время сохранения состояния HCD %d ms\n", m_szObjName, d );  OutputDebugString( szDebug );  return 0;}int KHcdRsu::StateRestoreL( HANDLE hRest ){  OutputDebugString( m_szObjName );  OutputDebugString( "     HCD::RestoreState...\n" );  DWORD s = GetTickCount();  KStateSer restorerImpl( hRest, false );  int r = restorerImpl.StartRestore();  ASS( r );  if( !r )    return !r;  DWORD savedVer = -1;  EKeys key = sKeyNULL;  restorerImpl.Read( key );  ASSD( sKeyVersion==key );  if( sKeyVersion!=key )    return 2;  restorerImpl.Read( savedVer );  ASS( s_VersionState==savedVer );  IStateSer &restorer = restorerImpl;  restorerImpl.Read( key );  ASSD( sKeySheetCount==key );  DWORD savedSheets = 0;  restorerImpl.Read( savedSheets );  char buffer[128];  DWORD WorksheetIndex;  for( size_t s=0; s<savedSheets; ++s )  {    restorerImpl.Read( key );    ASSD( sKeySheet==key );    DWORD L = restorer.Read( buffer );    ASSD( L );    restorer.Read( WorksheetIndex );    DWORD length = 0;    restorer.Read( length );    KHcdSheet* pSheet = NULL;    for( size_t n=0; n<m_nSheets; ++n )    {      KHcdSheet* pS = &m_pSheets[n];      if( pS->WorksheetIndex!=WorksheetIndex )        continue;      ASSD( !strcmp(pS->GetTreeName(), buffer) );      pSheet = pS;      break;    }    ASSD( pSheet );    int r = pSheet->RestoreState( restorer, savedVer );    ASSD( !r );  }  restorerImpl.Read( key );  ASSD( sKeyEnd==key );  DWORD c = GetTickCount();  DWORD d = c - s;  char szDebug[512] = {};  sprintf_s( szDebug, "%s   время восстановления состояния HCD %d ms\n", m_szObjName, d );  OutputDebugString( szDebug );  return 0;}